/*
 * A001326  Number of equivalence classes of n-valued Post functions of 2
 *          variables under action of semi-direct product of symmetric group
 *          S_2 and complementing group D(2,n).
 * https://oeis.org/A001326
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (n^(n^2) + 2*n^(n*ceil(n/2)) + 2*n^(n(n+1)/2) +
 *            n^((n^2+f)/2) + 2*n^((n^2+3f)/4)) / 8, where f = n mod 2
 *            (Burnside over the order-8 group generated by swapping and
 *            complementing inputs)
 * Range:     u8 n <= 2, u16 n <= 3, u32 n <= 4, u64 n <= 5, u128 n <= 6,
 *            big any n
 * Validated: partial, pass, 8 terms through n = 9 (2026-11-01)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

/* x = 8*T + R, with 0 <= R < 8 */
static void a001326_mul(seq_t *T1, unsigned *R1, seq_t T2, unsigned R2)
{
    seq_t t = *T1;
    unsigned r = *R1;
    seq_t nt = t * (T2 * 8 + R2) + T2 * r + (seq_t)((r * R2) / 8);
    *T1 = nt;
    *R1 = (r * R2) % 8;
}

static void a001326_pow(idx_t b, idx_t e, seq_t *T, unsigned *R)
{
    seq_t rt = 0;
    unsigned rr = 1;
    seq_t bt = (seq_t)(b / 8);
    unsigned br = (unsigned)(b % 8);
    while (e > 0) {
        if (e & 1) a001326_mul(&rt, &rr, bt, br);
        e >>= 1;
        if (e > 0) {
            seq_t ct = bt;
            unsigned cr = br;
            a001326_mul(&bt, &br, ct, cr);
        }
    }
    *T = rt;
    *R = rr;
}

seq_t a(idx_t n)
{
    idx_t f = n % 2;
    idx_t h = (n + 1) / 2;
    idx_t ex[5];
    unsigned w[5] = {1, 2, 2, 1, 2};
    seq_t sumT = 0;
    unsigned sumR = 0;
    int i;
    ex[0] = n * n;
    ex[1] = h * n;
    ex[2] = n * (n + 1) / 2;
    ex[3] = (n * n + f) / 2;
    ex[4] = (n * n + 3 * f) / 4;
    for (i = 0; i < 5; i++) {
        seq_t T;
        unsigned R;
        a001326_pow(n, ex[i], &T, &R);
        sumT += T * w[i];
        sumR += R * w[i];
    }
    return sumT + (seq_t)(sumR / 8);
}
